import { IconChevronLeft, IconChevronRight } from '@tabler/icons-react';

/** Prev/next arrows: one spread per click (0 → 1 opens the cover). */
export function Pager({
  page,
  pageCount,
  onChange,
}: {
  page: number;
  pageCount: number;
  onChange: (page: number) => void;
}) {
  const lastFace = pageCount * 2 - 1;

  return (
    <Group justify="center" gap="md">
      <ActionIcon
        variant="default"
        radius="xl"
        size="lg"
        aria-label="Previous page"
        disabled={page === 0}
        onClick={() => onChange(Math.max(0, page - 2))}
      >
        <IconChevronLeft size={18} />
      </ActionIcon>
      <ActionIcon
        variant="default"
        radius="xl"
        size="lg"
        aria-label="Next page"
        disabled={page === lastFace}
        onClick={() => onChange(page === 0 ? 1 : Math.min(lastFace, page + 2))}
      >
        <IconChevronRight size={18} />
      </ActionIcon>
    </Group>
  );
}`,lf=`/** An inner paper page: warm paper tone, dark ink page number. */
